export const BODY: string = "\n<p>تصویر میں بارڈر بڑھانے میں صرف چند منٹ لگتے ہیں۔ آپ تصویر اپ لوڈ کرتے ہیں، انداز چنتے ہیں، سائز اور رنگ سیٹ کرتے ہیں، اور فریم شدہ نتیجہ ڈاؤن لوڈ کرتے ہیں۔</p>\n<p>یہ کیسے کریں پورا عمل قدم بہ قدم بتاتا ہے۔ اس میں ٹھوس، پولرائڈ، اور گریڈینٹ گلو انداز، کونے کا رداس، ڈراپ شیڈو، اور ایکسپورٹ سیٹنگ شامل ہیں۔</p>\n<p>آخر تک آپ کسی بھی آلے پر سوشل میڈیا، پرنٹ، یا پروڈکٹ لسٹنگ کے لیے تصویر فریم کر سکیں گے۔ اصل تصویر رکھیں جب تک آپ نتیجہ چیک نہ کر لیں۔</p>\n<h2 id=\"before-you-start\">شروع کرنے سے پہلے: شکل چنیں</h2>\n<p>ٹول کھولنے سے پہلے فیصلہ کریں کہ بارڈر کس لیے ہے۔ سوشل پوسٹ کو پتلا، صاف فریم چاہیے ہوتا ہے، جبکہ پرنٹ کو چوڑا میٹ طرز بارڈر چاہیے ہوتا ہے۔</p>\n<p>رنگ کے بارے میں بھی سوچیں۔ سفید محفوظ ترین انتخاب ہے، سیاہ ڈرامہ بڑھاتا ہے، اور تصویر سے میل کھانے والا رنگ ڈیزائن شدہ احساس دیتا ہے۔</p>\n<p>کمپریس شدہ کاپی کے بجائے اصل تصویر استعمال کریں۔ تیز اصل پر بڑھایا گیا بارڈر صاف لگتا ہے، جبکہ نرم کاپی پر بڑھایا گیا کناروں پر کھردرا لگتا ہے۔</p>\n<p>اپنے براؤزر میں <a href=\"/ur/tasveer-par-border-lagayein/\">Image Border Generator</a> کھولیں۔ سب کچھ مقامی طور پر چلتا ہے، اس لیے آپ کی تصویر کبھی سرور پر اپ لوڈ نہیں ہوتی۔</p>\n<h2 id=\"step-by-step\">چھ قدموں میں بارڈر بڑھائیں</h2>\n<p>عمل ہر بارڈر انداز کے لیے ایک جیسا ہے۔ اپ لوڈ کریں، انداز چنیں، سائز اور رنگ سیٹ کریں، پیش نظارہ چیک کریں، اور ڈاؤن لوڈ کریں۔</p>\n<p>سائز اور رنگ کے ساتھ وقت لیں۔ وہ دو سیٹنگ طے کرتی ہیں کہ بارڈر تصویر کو فریم کرتا ہے یا اس پر حاوی ہوتا ہے۔</p>\n<p>شیئر کرنے سے پہلے ڈاؤن لوڈ شدہ فائل کو ایک بار کھولیں۔ تصدیق کریں کہ بارڈر تمام طرف برابر ہے اور اندر کی تصویر پھر بھی اچھی لگتی ہے۔</p>\n<h2 id=\"choosing-border-style\">بارڈر انداز چننا</h2>\n<p>ٹھوس بارڈر برابر چوڑائی والا واحد رنگ بینڈ ہے۔ یہ سب سے آسان انداز ہے، اور یہ تقریباً کسی بھی تصویر کے لیے موزوں ہے، پورٹریٹ سے پروڈکٹ شاٹ تک۔</p>\n<p>پولرائڈ بارڈر فوری فلم کی نقل کرتا ہے، کیپشن کے لیے نیچے موٹا بینڈ کے ساتھ۔ یہ پرانی یادوں والا اور آرام دہ محسوس ہوتا ہے، جو چھٹی تصاویر اور یادوں کے لیے موزوں ہے۔</p>\n<p>گریڈینٹ گلو فریم تصویر کے گرد رنگ ملاتا ہے تاکہ جدید، ڈیجیٹل نظر آئے۔ یہ سوشل گرافکس اور پوسٹر کے لیے موزوں ہے، جہاں فریم ڈیزائن کا حصہ ہے۔</p>\n<p>اگر آپ غیر یقینی ہوں تو ٹھوس سے شروع کریں۔ یہ محفوظ ترین انتخاب ہے، اور آپ فینسی انداز پر جا سکتے ہیں جب آپ دیکھ لیں کہ تصویر فریم شدہ کیسی لگتی ہے۔</p>\n<h2 id=\"setting-border-size\">بارڈر سائز سیٹ کرنا</h2>\n<p>بارڈر سائز تصویر کے 1 فیصد سے 25 فیصد تک چلتا ہے۔ 1 سے 3 فیصد کا پتلا بارڈر تصویر کو فریم کرتا ہے بغیر اس سے توجہ لیے۔</p>\n<p>5 سے 10 فیصد کا درمیانی بارڈر گیلری احساس بناتا ہے۔ یہ تصویر کو سانس لینے کی جگہ دیتا ہے اور پرنٹ، پورٹ فولیو، اور پریزنٹیشن سلائیڈ کے لیے موزوں ہے۔</p>\n<p>15 فیصد سے اوپر بڑا بارڈر ڈیزائن بیان بن جاتا ہے۔ یہ پوسٹر اور سوشل گرافکس کے لیے موزوں ہے، جہاں فریم نظر کا حصہ ہے۔</p>\n<p>یاد رکھیں کہ بارڈر کل سائز میں بڑھتا ہے۔ ہر طرف 10 فیصد بارڈر والی تصویر اصل سے 20 فیصد چوڑی اور لمبی ہوتی ہے۔</p>\n<h2 id=\"choosing-colour\">بارڈر رنگ چننا</h2>\n<p>سفید محفوظ ترین بارڈر رنگ ہے۔ یہ کسی بھی تصویر کے لیے موزوں ہے، کسی بھی پس منظر پر کام کرتا ہے، اور تصویر کو صاف، گیلری احساس دیتا ہے جو کبھی پرانا نہیں لگتا۔</p>\n<p>سیاہ ڈرامہ اور توجہ بڑھاتا ہے۔ یہ مزاجی تصاویر، رات کے شاٹس، اور فائن آرٹ کے لیے موزوں ہے، جہاں ہلکا بارڈر جگہ سے باہر محسوس ہو گا۔</p>\n<p>ڈیزائن شدہ نظر کے لیے بارڈر کو تصویر کے رنگ سے ملائیں۔ لباس، آسمان، یا پروڈکٹ کا رنگ اٹھانے والا بارڈر فریم کو تصویر سے جوڑتا ہے۔</p>\n<p>فوری پری سیٹ پر کلک کرنے کے بعد بھی آپ فریم رنگ بدل سکتے ہیں۔ پری سیٹ نقطہ آغاز ہیں، تالا نہیں، اس لیے رنگ کو اپنی تصویر کے مطابق ایڈجسٹ کریں۔</p>\n<h2 id=\"setting-corner-radius\">کونے کا رداس سیٹ کرنا</h2>\n<p>فریم رداس بارڈر کے بیرونی کنارے کی گولائی کنٹرول کرتا ہے، جبکہ تصویر رداس اندرونی کنارے کی گولائی کنٹرول کرتا ہے جہاں بارڈر تصویر سے ملتا ہے۔</p>\n<p>دونوں کو ایک ہی قدر پر سیٹ کرنا یکساں گول فریم دیتا ہے۔ نتیجہ صاف، مستقل خم ہوتا ہے جو کارڈ اور سوشل پوسٹ پر پیشہ ورانہ لگتا ہے۔</p>\n<p>سادہ مربع فریم کے لیے دونوں رداس کو صفر پر رکھیں۔ تیز کونے رسمی تصاویر اور پروڈکٹ شاٹ کے لیے موزوں ہیں، جہاں گول کنارہ جگہ سے باہر محسوس ہو گا۔</p>\n<p>پولرائڈ انداز کے لیے رداس کم رکھیں۔ کلاسک فوری فلم نظر میں مربع کونے ہوتے ہیں، اور انہیں بہت گول کرنا ریٹرو احساس توڑ دیتا ہے۔</p>\n<h2 id=\"adding-drop-shadow\">ڈراپ شیڈو بڑھانا</h2>\n<p>ڈراپ شیڈو فریم شدہ تصویر کے پیچھے نرم تاریک کنارہ بڑھاتا ہے، جو اسے ایسا بناتا ہے جیسے یہ صفحے کے اوپر تیر رہی ہو۔ یہ گہرائی اور پالش بڑھاتا ہے۔</p>\n<p>سائے ہلکے پس منظر پر بہترین کام کرتے ہیں، جہاں تاریک کنارہ نظر آتا ہے۔ تاریک پس منظر پر سایہ مل جاتا ہے اور تصویر میں کم بڑھاتا ہے۔</p>\n<p>سایہ رکھنے کے لیے PNG یا WebP کے طور پر ایکسپورٹ کریں۔ JPG میں کوئی شفافیت نہیں ہوتی، اس لیے سایہ JPG ایکسپورٹ میں غائب ہو جاتا ہے اور نتیجہ فلیٹ لگتا ہے۔</p>\n<p>بغیر سائے والے تاریک چارکول یا پیسٹل فریم کے لیے سایہ بند کریں اور رنگ سیدھا چنیں۔ بغیر سائے والا صاف فریم کم سے کم ڈیزائن کے لیے موزوں ہے۔</p>\n<h2 id=\"using-quick-presets\">فوری فریم پری سیٹ استعمال کرنا</h2>\n<p>ٹول میں چار فوری فریم پری سیٹ شامل ہیں، ہر ایک ایک کلک میں انداز، سائز، رنگ، اور سایہ سیٹ کرتا ہے۔ وہ عام نظاروں کے لیے تیز نقطہ آغاز ہیں۔</p>\n<p>پری سیٹ پر کلک کریں تاکہ دیکھیں کہ کون سا آپ کی تصویر کے لیے موزوں ہے۔ پیش نظارہ فوراً اپ ڈیٹ ہوتا ہے، اس لیے آپ نظاروں کا موازنہ سیکنڈوں میں کر سکتے ہیں۔</p>\n<p>پری سیٹ پر کلک کرنے کے بعد کوئی بھی سیٹنگ بدلیں جو آپ چاہیں۔ رنگ، سائز، اور سایہ سب ایڈجسٹ ہو سکتے ہیں، اس لیے پری سیٹ بنیاد ہے، حتمی جواب نہیں۔</p>\n<p>تصاویر کے سیٹ میں مستقل نظر کے لیے ان سب کے لیے ایک ہی پری سیٹ استعمال کریں۔ میل کھانے والے فریم والی تصاویر کا بیچ سیریز کی طرح لگتا ہے۔</p>\n<h2 id=\"polaroid-border\">پولرائڈ بارڈر بنانا</h2>\n<p>بارڈر آپشن میں پولرائڈ انداز چنیں۔ ٹول کلاسک شکل خود بخود لگاتا ہے، بشمول نیچے موٹا بینڈ۔</p>\n<p>نیچے والا بینڈ کیپشن کے لیے جگہ دیتا ہے۔ ایکسپورٹ کے بعد وہاں <a href=\"/ur/tasveer-par-text-likhein/\">Add Text to Image tool</a> سے متن بڑھائیں، یا صاف ریٹرو نظر کے لیے اسے خالی چھوڑ دیں۔</p>\n<p>پولرائڈ فریم کے لیے کونے کا رداس کم رکھیں۔ کلاسک فوری فلم نظر میں مربع کونے ہوتے ہیں، اور انہیں بہت گول کرنا اثر توڑ دیتا ہے۔</p>\n<p>پولرائڈ بارڈر آرام دہ، ذاتی تصاویر کے لیے بہترین موزوں ہیں۔ وہ رسمی پورٹریٹ یا پروڈکٹ شاٹ پر جگہ سے باہر محسوس ہوتے ہیں، جہاں صاف ٹھوس بارڈر زیادہ مناسب ہے۔</p>\n<h2 id=\"gradient-glow-frame\">گریڈینٹ گلو فریم بنانا</h2>\n<p>گریڈینٹ گلو انداز چنیں اور زاویہ اور رنگ سیٹ کریں۔ گلو تصویر کے گرد دو یا اس سے زیادہ رنگ ملاتا ہے، نرم، چمکتا ہوا کنارہ بناتا ہے۔</p>\n<p>زاویہ بدلنا ملاوٹ کو فریم کے گرد منتقل کرتا ہے۔ وہی رنگ بہت سے مختلف نظارے پیدا کر سکتے ہیں، اس لیے چند زاویے آزمائیں اور دیکھیں کہ کون سا آپ کی تصویر کے لیے موزوں ہے۔</p>\n<p>گریڈینٹ فریم تاریک تصاویر پر اچھی طرح کام کرتے ہیں، جہاں روشن کنارہ توانائی بڑھاتا ہے۔ وہ ہلکی، ہوائی تصویر کو مغلوب کر سکتے ہیں، اس لیے انہیں تب استعمال کریں جب تصویر کو ڈرامہ چاہیے ہو۔</p>\n<p>پیشہ ورانہ کام کے لیے گلو کو معمولی رکھیں۔ نرم گریڈینٹ پالش بڑھاتا ہے، جبکہ سخت، روشن گلو تصویر سے توجہ ہٹاتا ہے۔</p>\n<h2 id=\"preview-and-compare\">ڈاؤن لوڈ سے پہلے پیش نظارہ</h2>\n<p>ڈاؤن لوڈ سے پہلے ہمیشہ پیش نظارہ کریں۔ چیک کریں کہ بارڈر تمام طرف برابر ہے، کونے درست لگتے ہیں، اور رنگ تصویر کے لیے موزوں ہے۔</p>\n<p>پیش نظارہ فریم کے گرد سرمئی اور سفید چیکر بورڈ دکھاتا ہے۔ وہ نمونہ شفافیت کا مطلب ہے، سرمئی پس منظر نہیں، اور یہ دکھاتا ہے کہ تصویر کہاں دیکھنے والی ہے۔</p>\n<p>اگر آپ نے سایہ بڑھایا تو اسے ہلکے پس منظر پر چیک کریں۔ تاریک پیش نظارہ پر پوشیدہ سایہ سفید صفحے پر صاف ہو سکتا ہے جہاں تصویر رہے گی۔</p>\n<p>اگر بارڈر بہت موٹا یا بہت پتلا لگے تو سائز ایڈجسٹ کریں اور دوبارہ چیک کریں۔ فیصد میں چھوٹی تبدیلی فریم کے احساس میں بڑا فرق کر سکتی ہے۔</p>\n<h2 id=\"choosing-export-format\">ایکسپورٹ فارمیٹ چننا</h2>\n<p>جب فریم میں گول کونے یا ڈراپ شیڈو ہوں تو PNG چنیں۔ PNG شفافیت محفوظ رکھتا ہے، اس لیے کونے دیکھنے والے رہتے ہیں اور سایہ بچتا ہے۔</p>\n<p>شفافیت کے ساتھ چھوٹی فائلیں چاہیے ہوں تو WebP چنیں۔ یہ ویب تصاویر کے لیے اچھی طرح کام کرتا ہے، اگرچہ چند پرانے سسٹم پھر بھی فارمیٹ مسترد کرتے ہیں۔</p>\n<p>JPG صرف بغیر سائے والے ٹھوس مستطیل بارڈر کے لیے چنیں۔ JPG سب کچھ ٹھوس پس منظر پر فلیٹ کرتا ہے، جو سادہ فریم کے لیے ٹھیک ہے۔</p>\n<p>یاد رکھیں کہ کوالٹی سلائیڈر PNG کے لیے چھپتا ہے، کیونکہ PNG لاس لیس ہے اور اس کی کوئی کوالٹی سیٹنگ نہیں جسے ایڈجسٹ کریں۔ یہ معمول رویہ ہے، ٹول کا مسئلہ نہیں۔</p>\n<h2 id=\"adding-border-on-mobile\">فون یا ٹیبلیٹ پر بارڈر بڑھانا</h2>\n<p>ٹول ٹچ اسکرین پر کام کرتا ہے، اس لیے آپ اس فون پر تصویر فریم کر سکتے ہیں جس نے اسے لیا۔ اپنی گیلری سے اپ لوڈ کریں، پری سیٹ چنیں، اور نتیجہ ڈاؤن لوڈ کریں۔</p>\n<p>چھوٹی اسکرین پر فوری پری سیٹ آسان ترین راستہ ہیں۔ ایک ٹیپ انداز، سائز، رنگ، اور سایہ سیٹ کرتا ہے، اور آپ ضرورت پڑنے پر وہاں سے ایڈجسٹ کر سکتے ہیں۔</p>\n<p>ڈاؤن لوڈ سے پہلے پیش نظارہ کو پورے سائز پر چیک کریں۔ چھوٹی فون اسکرین پر ٹھیک لگنے والا بارڈر کمپیوٹر پر دیکھنے پر بہت موٹا یا بہت پتلا ہو سکتا ہے۔</p>\n<p>ڈاؤن لوڈ شدہ فائلیں آپ کے معمول کے ڈاؤن لوڈ فولڈر میں محفوظ ہوتی ہیں۔ وہاں سے آپ فریم شدہ تصویر کو سیدھا چیٹ ایپ، ای میل، یا سوشل پوسٹ پر شیئر کر سکتے ہیں۔</p>\n<h2 id=\"troubleshooting\">عام بارڈر مسائل کا حل</h2>\n<p>اگر ڈراپ شیڈو غائب ہو گیا تو ایکسپورٹ فارمیٹ چیک کریں۔ JPG میں کوئی شفافیت نہیں ہوتی، اس لیے سایہ صرف PNG یا WebP ایکسپورٹ میں بچتا ہے۔</p>\n<p>اگر کونے مربع لگتے ہیں جب آپ انہیں گول چاہتے تھے تو فریم رداس اور تصویر رداس چیک کریں۔ یکساں گول فریم کے لیے دونوں کو سیٹ کرنا ہوتا ہے۔</p>\n<p>اگر بارڈر غیر برابر لگے تو سائز سیٹنگ چیک کریں۔ فیصد کے طور پر سیٹ شدہ بارڈر لمبی اور چوڑی تصاویر پر مختلف لگ سکتا ہے، اس لیے اسے شکل کے لیے ایڈجسٹ کریں۔</p>\n<p>اگر فریم شدہ تصویر اپنی منزل کے لیے بہت بڑی ہو تو بارڈر سائز کم کریں یا پہلے تصویر کو سائز بدلیں۔ بارڈر کل ابعاد میں بڑھتا ہے، اس لیے چوڑا فریم فائل کو بڑا بنا سکتا ہے۔</p>\n<h2 id=\"framing-screenshots\">اسکرین شاٹ فریم کرنا</h2>\n<p>محفوظ کرنے کا قدم چھوڑنے کے لیے اسکرین شاٹ کو Ctrl+V سے سیدھا چسپاں کریں۔ تصویر ٹول میں فوراً ظاہر ہوتی ہے، فریم کے لیے تیار۔</p>\n<p>نرم سائے والا پتلا سفید بارڈر اسکرین شاٹ کو کارڈ کی طرح بناتا ہے۔ یہ اسکرین کیپچر کو صفحے سے الگ کرتا ہے اور اسے پالش لگاتا ہے۔</p>\n<p>اسکرین شاٹ کے لیے بارڈر پتلا رکھیں۔ موٹا فریم وہ جگہ لیتا ہے جسے اسکرین شاٹ مواد چاہیے ہوتا ہے، خاص طور پر جب کیپچر میں متن چھوٹا ہو۔</p>\n<p>فریم شدہ اسکرین شاٹ کو PNG کے طور پر ایکسپورٹ کریں۔ لاس لیس فارمیٹ چھوٹے متن کو تیز رکھتا ہے، جو اہمیت رکھتا ہے جب اسکرین شاٹ کو سیٹنگ یا غلطی پیغام دکھانا ہو۔</p>\n<h2 id=\"quick-tips\">بہتر بارڈر کے لیے فوری نکات</h2>\n<p>پری سیٹ سے شروع کریں اور وہاں سے ایڈجسٹ کریں۔ فوری فریم ایک کلک میں اچھی بنیاد دیتے ہیں، اور باریک ٹیوننگ میں صرف چند سیکنڈ لگتے ہیں۔</p>\n<p>سوشل میڈیا کے لیے بارڈر پتلا رکھیں۔ موٹا فریم چھوٹے فیڈ پیش نظارہ میں جگہ لیتا ہے، تصویر کے لیے کم جگہ چھوڑتا ہے۔</p>\n<p>تصاویر کے سیٹ میں ایک ہی بارڈر انداز استعمال کریں۔ مستقل مزاجی سیریز کو پیشہ ورانہ بناتی ہے، جبکہ ملے ہوئے فریم بے ترتیب لگتے ہیں۔</p>\n<p>اصل تصویر کو بغیر بارڈر کے محفوظ کریں۔ ایک بار ایکسپورٹ میں فلیٹ شدہ بارڈر اس فائل سے ہٹایا نہیں جا سکتا، اس لیے اصل ہی آپ کی واحد صاف کاپی ہے۔</p>\n<h2 id=\"border-for-presentation\">پریزنٹیشن سلائیڈ تصویر میں بارڈر بڑھانا</h2>\n<p>سلائیڈ پر استعمال شدہ تصویر کو اکثر سلائیڈ پس منظر سے الگ کرنے کے لیے بارڈر چاہیے ہوتا ہے۔ نرم سائے والا پتلا سفید فریم تصویر کو سلائیڈ پر کارڈ کی طرح بناتا ہے۔</p>\n<p>سلائیڈ کے لیے بارڈر پتلا رکھیں۔ موٹا فریم وہ جگہ لیتا ہے جسے تصویر اور متن چاہیے ہوتا ہے، خاص طور پر جب سلائیڈ میں پہلے سے عنوان اور بلٹ پوائنٹ ہوں۔</p>\n<p>بارڈر رنگ کو سلائیڈ تھیم سے ملائیں۔ سفید بارڈر ہلکے تھیم کے لیے موزوں ہے، جبکہ تاریک بارڈر تاریک تھیم کے لیے موزوں ہے، اور بے میل فریم حادثاتی لگتا ہے۔</p>\n<p>فریم شدہ سلائیڈ تصویر کو اعلیٰ کوالٹی سیٹنگ پر JPG کے طور پر ایکسپورٹ کریں۔ سلائیڈ بڑی پروجیکٹ ہو گی، اس لیے تصویر اور بارڈر دونوں کو تیز رہنا چاہیے۔</p>\n<p>انداز خیالات کے لیے <a href=\"/ur/blog/tasveer-frames-borders-styles/\">Image Frames and Borders: Styles for Social and Print</a> پڑھیں۔ مکمل جائزے کے لیے <a href=\"/ur/blog/tasveer-border-generator-rehnumai/\">Image Borders: Complete Guide</a> دیکھیں، اور کونوں کو گول کرنے کے لیے <a href=\"/ur/tasveer-ke-kone-gol-karein/\">Round Image Corners tool</a> استعمال کریں۔</p>\n<ul>\n<li>اپنی تصویر ڈراپ زون میں گھسیٹ کر، اپنے آلے سے چن کر، یا Ctrl+V سے اسکرین شاٹ چسپاں کر کے اپ لوڈ کریں۔</li>\n<li>بارڈر انداز چنیں: Solid، Polaroid، یا Gradient Glow، یا چار فوری فریم پری سیٹ میں سے ایک سے شروع کریں۔</li>\n<li>بارڈر سائز 1% اور 25% کے درمیان سیٹ کریں، اور فریم رنگ چنیں جو آپ کی تصویر کے لیے موزوں ہو۔</li>\n<li>گول کونوں کے لیے فریم رداس اور تصویر رداس ایڈجسٹ کریں، اور اگر آپ گہرائی چاہتے ہیں تو ڈراپ شیڈو بڑھائیں۔</li>\n<li>نتیجہ کا پیش نظارہ کریں، کونوں اور سائے کو ہلکے اور تاریک دونوں پس منظر پر چیک کریں۔</li>\n<li>ایکسپورٹ فارمیٹ چنیں، شفافیت اور سائے رکھنے کے لیے PNG یا WebP، پھر Download پر کلک کریں۔</li>\n</ul>\n";

